示例2：九九乘法表：

public class NestedLoopDemo2 {
    public static void main(String[] args) {
        // 外层循环：控制行数（1-9行）
        for (int i = 1; i <= 9; i++) {
            // 内层循环：控制列数（1-i列）
            for (int j = 1; j <= i; j++) {
                System.out.print(j + "×" + i + "=" + (i*j) + "\t"); // \t是制表符，对齐
            }
            System.out.println(); // 每行结束后换行
        }
